arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) echo "x-access-token" ;;
*Password*) echo "$GITHUB_TOKEN" ;;
*) echo "" ;;
esac
EOF
chmod +x /tmp/askpass.sh
cd /tmp/joey-conv && GIT_ASKPASS=/tmp/askpass.sh git push origin HEAD:refs/heads/friend/joey 2>&1 | tail -10
